import{_ as a,o as e,c as i,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"时间与资源排程 Gantt","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/gantt/index.md","filePath":"zh-cn/frameworks/gantt/index.md"}'),o={name:"zh-cn/frameworks/gantt/index.md"};function d(l,t,n,h,c,s){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="时间与资源排程-gantt" tabindex="-1">时间与资源排程 Gantt <a class="header-anchor" href="#时间与资源排程-gantt" aria-label="Permalink to &quot;时间与资源排程 Gantt&quot;">​</a></h1><p>为活动选择执行方式和开始时间，同时安排设备、人员等资源，并满足依赖、工作日历与物料事件。第一课使用有限候选活动 MILP，不需要把活动先变成路径。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>活动</td><td><code>Activity</code></td><td>业务工作单元；取消需显式声明代价</td></tr><tr><td>执行模式</td><td><code>ActivityMode</code></td><td>时长、允许起点、费用和资源占用段</td></tr><tr><td>资源</td><td><code>ActivityResource</code></td><td>容量、不可用区间与时变容量</td></tr><tr><td>依赖</td><td><code>ActivityDependency</code></td><td>活动端点关系及时间界限</td></tr><tr><td>问题与结果</td><td><code>ActivitySchedulingProblem</code> / <code>ActivitySchedule</code></td><td>候选、排程、占用、取消与库存</td></tr></tbody></table><p>允许起点是业务域，不是搜索预算：只给 08:00 和 10:00，不会暗中允许 09:00 开始。资源占用采用半开区间，起点可用不代表执行全程可用。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>两种语言都有 <code>ActivitySchedulingApplicationService</code>。独立服务与嵌入式 context 共享领域注册。复用 <code>ColumnGenerationSolver</code> 的 MILP 能力，不代表这个活动入口执行列生成。</p><p>APS / MPS / LSP 是业务层级标记，不是本课的独立求解入口。任务束、产能和分支定价是后续求解路径。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>不承诺任意连续时间排程、自动抢占/分批或完整行业法规。</li><li>工作日历不可用区间不会自动转化为“暂停后继续执行”。</li><li>联合资源和物料库存是不同契约；多人技能组容量不替代具名人员互斥。</li><li>普通 Gantt 不强制依赖 Network；跨地点行驶子问题才需要评估组合。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-schedule.html">第一次活动排程</a>，检查模式、依赖和资源占用。</li><li>加入停机、基线调整与物料事件，区分已执行事实和待优化决策。</li><li>阅读<a href="/ospf/zh-cn/guide/rolling-optimization.html">滚动优化</a>，再看<a href="/ospf/zh-cn/examples/framework-example4.html">航班恢复综合案例</a>。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-gantt-scheduling/gantt-scheduling-domain-activity-context/README_ch.md" target="_blank" rel="noreferrer">Kotlin 活动契约</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-gantt-scheduling/src/domain/activity/README_ch.md" target="_blank" rel="noreferrer">Rust 活动契约</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">停机日历与滚动重排</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const f=a(o,[["render",d]]);export{u as __pageData,f as default};
